mapper.select:
select
wmim.*
from wms_material_inventory_manufactured wmim
where wmim.bool_delete_enum = 0
and wmim.quantity != 0

    and wmim.basic_class & #{basicClass} > 0


    and wmim.monomer_id = #{monomerId}


    and wmim.area_id = #{areaId}


    and wmim.project_id = #{projectId}


    and wmim.manufactured_name like concat('%',#{manufacturedName},'%')


    and wmim.manufactured_sn like concat('%',#{manufacturedSn},'%')


    and wmim.specification like concat('%',#{specification},'%')


    and wmim.color like concat('%',#{color},'%')


    and wmim.brand like concat('%',#{brand},'%')


    and wmim.workshop_id = #{workshopId}


    and wmim.warehouse_id = #{warehouseId}


    and wmim.workshop_id in
    
        #{item}
